<?php
require __DIR__ . '/app/core.php';
require_login();
$csrf=csrf_token();
$demos=list_demos(false);
?>
<!doctype html><html lang="tr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Demo Siteler</title><link rel="stylesheet" href="assets/style.css?v=44"></head><body><main class="standalone-page"><div class="page-actions"><a class="btn ghost" href="index.php">← Panele Dön</a></div><section class="card"><div class="section-head"><div><h1>Demo Site Yönetimi</h1><p>Müşteriye WhatsApp’tan göndereceğin örnek tasarımları buradan yönet.</p></div></div><form id="demoForm" class="form-grid large-form"><input type="hidden" id="demoId"><label>Demo adı<input id="demoTitle" placeholder="Güzellik salonu demo"></label><label>Sektör<input id="demoSector" placeholder="Güzellik / Kombi / Sanayi"></label><label class="wide-2">Demo linki<input id="demoUrl" placeholder="https://..."></label><label>Görsel URL / dosya yolu<input id="demoImage" placeholder="uploads/demo.jpg"></label><label>Aktif mi?<select id="demoActive"><option value="1">Aktif</option><option value="0">Pasif</option></select></label><label class="wide-full">Not<textarea id="demoNote" rows="3"></textarea></label><div class="actions-row wide-full"><button class="btn primary" type="submit">Kaydet</button><button class="btn ghost" type="button" onclick="clearDemo()">Temizle</button></div></form></section><section class="card"><h2>Kayıtlı Demolar</h2><div class="demo-grid" id="demoGrid"><?php foreach($demos as $d): ?><article class="demo-card"><b><?=e($d['title'])?></b><span><?=e($d['sector'])?></span><a href="<?=e($d['url'])?>" target="_blank"><?=e($d['url'])?></a><p><?=e($d['note'])?></p><small><?=!empty($d['is_active'])?'Aktif':'Pasif'?></small><div class="row-actions"><button class="btn secondary mini" onclick='editDemo(<?=json_encode($d, JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)?>)'>Düzenle</button><button class="btn danger mini" onclick="deleteDemo(<?= (int)$d['id']?>)">Sil</button></div></article><?php endforeach; ?></div></section></main><script>const CSRF=<?=json_encode($csrf)?>;function $(s){return document.querySelector(s)}function clearDemo(){['demoId','demoTitle','demoSector','demoUrl','demoImage','demoNote'].forEach(id=>$('#'+id).value='');$('#demoActive').value='1'}function editDemo(d){$('#demoId').value=d.id||'';$('#demoTitle').value=d.title||'';$('#demoSector').value=d.sector||'';$('#demoUrl').value=d.url||'';$('#demoImage').value=d.image||'';$('#demoNote').value=d.note||'';$('#demoActive').value=String(d.is_active??1);scrollTo({top:0,behavior:'smooth'})}async function deleteDemo(id){if(!confirm('Silinsin mi?'))return; await fetch('api/demos.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({csrf:CSRF,action:'delete',id})}); location.reload()}$('#demoForm').addEventListener('submit',async e=>{e.preventDefault(); const payload={csrf:CSRF,id:$('#demoId').value,title:$('#demoTitle').value,sector:$('#demoSector').value,url:$('#demoUrl').value,image:$('#demoImage').value,note:$('#demoNote').value,is_active:$('#demoActive').value==='1'}; const r=await fetch('api/demos.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)}); const d=await r.json(); if(!d.ok) alert(d.error||'Kaydedilemedi'); else location.reload();});</script></body></html>
